    .sound-wave {\n            height: 140px;\n            width: 100%;\n            background-color: rgba(0, 0, 0, 0.4);\n            border-radius: var(--border-radius);\n            overflow: hidden;\n            position: relative;\n            margin: 25px 0;\n            box-shadow: inset 0 0 15px rgba(0, 0, 0, 0.5);\n        }\n        \n        .visualization {\n            display: flex;\n            justify-content: space-around;\n            align-items: center;\n            height: 100%;\n            padding: 0 15px;\n        }\n        \n        .bar {\n            background: linear-gradient(180deg, var(--primary-light), var(--primary-dark));\n            width: 5px;\n            height: 30%;\n            border-radius: 10px;\n            transition: height 0.1s ease;\n        }\n        \n        .tone-controls {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 15px;\n            margin-top: 20px;\n        }\n        \n        .meaning-card {\n            background: rgba(255, 140, 64, 0.05);\n            border-left: 4px solid var(--primary);\n            padding: 25px;\n            margin-top: 25px;\n            border-radius: 0 var(--border-radius) var(--border-radius) 0;\n        }\n        \n        #tone-meaning {\n            line-height: 1.7;\n        }\n        \n        .copyright {\n            text-align: center;\n            padding: 15px;\n            color: var(--text-muted);\n            font-size: 0.8em;\n            margin-top: 20px;\n        }\n        \n        /* Animations */\n        @keyframes pulse {\n            0% { transform: scale(1); }\n            50% { transform: scale(1.03); }\n            100% { transform: scale(1); }\n        }\n        \n        @keyframes glow {\n            0% { box-shadow: 0 0 5px rgba(255, 140, 64, 0.2); }\n            50% { box-shadow: 0 0 20px rgba(255, 140, 64, 0.4); }\n            100% { box-shadow: 0 0 5px rgba(255, 140, 64, 0.2); }\n        }\n        \n        /* Responsive adjustments */\n        @media (max-width: 768px) {\n            .tone-controls {\n                grid-template-columns: 1fr;\n            }\n            \n            .app-header h1 {\n                font-size: 1.9em;\n            }\n            \n            .card-body {\n                padding: 20px;\n            }\n            \n            .number-circle {\n                width: 70px;\n                height: 70px;\n                font-size: 1.8em;\n            }\n            \n            .frequency-text {\n                font-size: 1.2em;\n            }\n        }\n    </style>\n</head>\n<body>\n    <div class=\"app-container\">\n        <div class=\"app-header\">\n            <h1>Numerology Tone Generator</h1>\n            <p>Discover the frequencies that resonate with your personal numbers</p>\n        </div>\n        \n        <div class=\"card\">\n            <div class=\"card-header\">\n                <h2>Calculate Your Numerology Tone</h2>\n            </div>\n            <div class=\"card-body\">\n                <div class=\"input-group\">\n                    <label for=\"calculation-type\">Calculation Method</label>\n                    <select id=\"calculation-type\">\n                        <option value=\"lifePath\">Life Path Number</option>\n                        <option value=\"birthDate\">Birth Date</option>\n                        <option value=\"name\">Name Number</option>\n                        <option value=\"custom\">Custom Number</option>\n                    </select>\n                </div>\n                \n                <div id=\"lifePath-input\" class=\"input-group\">\n                    <label for=\"birth-date\">Birth Date</label>\n                    <input type=\"date\" id=\"birth-date\">\n                </div>\n                \n                <div id=\"name-input\" class=\"input-group\" style=\"display: none;\">\n                    <label for=\"full-name\">Full Name</label>\n                    <input type=\"text\" id=\"full-name\" placeholder=\"Enter your full name\">\n                </div>\n                \n                <div id=\"custom-input\" class=\"input-group\" style=\"display: none;\">\n                    <label for=\"custom-number\">Custom Number (1-9)</label>\n                    <input type=\"number\" id=\"custom-number\" min=\"1\" max=\"9\" value=\"1\">\n                </div>\n                \n                <button id=\"calculate-btn\">Calculate & Generate Tone</button>\n            </div>\n        </div>\n        \n        <div class=\"card\">\n            <div class=\"card-header\">\n                <h2>Your Numerology Tone</h2>\n            </div>\n            <div class=\"card-body\">\n                <div class=\"result-display\">\n                    <div class=\"frequency-display\">\n                        <div class=\"number-circle\" id=\"number-display\">--</div>\n                        <div class=\"frequency-text\" id=\"frequency-display\">--- Hz</div>\n                    </div>\n                </div>\n                \n                <div class=\"sound-wave\">\n                    <div class=\"visualization\" id=\"visualization\">\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                        <div class=\"bar\"></div>\n                    </div>\n                </div>\n                \n                <div class=\"tone-controls\">\n                    <button id=\"play-btn\" disabled>Play Tone</button>\n                    <button id=\"stop-btn\" disabled>Stop Tone</button>\n                    <button id=\"harmonize-btn\" disabled>Harmonize</button>\n                </div>\n                \n                <div class=\"meaning-card\">\n                    <p id=\"tone-meaning\">Calculate your tone to see its meaning and vibration properties.</p>\n                </div>\n            </div>\n        </div>\n        \n        <div class=\"copyright\">\n            © 2025 Numerology Tone Generator • All frequencies based on ancient Solfeggio scale\n        </div>\n    </div>\n\n    <script>\n        // Audio context and oscillator\n        let audioContext;\n        let oscillator;\n        let gainNode;\n        let harmonicOscillators = [];\n        \n        // Numerology frequencies (based on Solfeggio frequencies and numerology)\n        const frequencies = {\n            1: 396, // Liberating guilt & fear\n            2: 417, // Undoing situations & facilitating change\n            3: 528, // Transformation & miracles\n            4: 639, // Connecting/relationships\n            5: 741, // Awakening intuition\n            6: 852, // Returning to spiritual order\n            7: 963, // Awakening to spiritual light\n            8: 174, // Pain relief & energy\n            9: 285, // Return to spiritual order\n        };\n        \n        // Meanings for each numerology number\n        const meanings = {\n            1: \"The number 1 resonates with the frequency of 396 Hz, which helps liberate guilt and fear. This tone assists in grounding and connecting with Earth energy. It\'s ideal for breaking free from fear patterns and past limiting behaviors.\",\n            2: \"The number 2 corresponds to 417 Hz, facilitating change and undoing situations. This frequency helps with resonant transformation and cleansing traumatic experiences. It\'s excellent for facilitating change and removing negative energy blocks.\",\n            3: \"The number 3 resonates at 528 Hz, known as the \'miracle tone\' associated with transformation and DNA repair. This frequency brings clarity and peace. It\'s connected to the heart chakra and is believed to facilitate healing and manifestation.\",\n            4: \"The number 4 vibrates at 639 Hz, connecting relationships and bridging divides. This tone harmonizes relationships and encourages understanding. It helps balance emotions and promotes communication and understanding with those around you.\",\n            5: \"The number 5 connects to 741 Hz, awakening intuition and expanding consciousness. This frequency helps with solving problems and expressing yourself. It cleanses the body from different types of electromagnetic radiation and is used for spiritual awakening.\",\n            6: \"The number 6 resonates with 852 Hz, returning to spiritual order. This tone awakens intuition and returns you to spiritual balance. It\'s powerful for opening your third eye and connecting with your higher consciousness.\",\n            7: \"The number 7 corresponds to 963 Hz, representing awakening and connection to spiritual light. This frequency creates room for oneness and unity consciousness. It\'s connected to the crown chakra and enables connection with your higher spiritual self.\",\n            8: \"The number 8 vibrates at 174 Hz, providing pain relief and releasing energy. This tone serves as a natural anesthetic and grounds your energy. It reduces pain on physical and emotional levels and provides a sense of security and comfort.\",\n            9: \"The number 9 connects to 285 Hz, bringing you back to spiritual order. This frequency helps you connect with your higher self and cosmic wisdom. It helps in remembering your true spiritual nature and reconnecting with universal energy fields.\"\n        };\n        \n        // DOM elements\n        const calculationType = document.getElementById(\'calculation-type\');\n        const birthDateInput = document.getElementById(\'birth-date\');\n        const nameInput = document.getElementById(\'full-name\');\n        const customInput = document.getElementById(\'custom-number\');\n        const lifePathInput = document.getElementById(\'lifePath-input\');\n        const nameInputDiv = document.getElementById(\'name-input\');\n        const customInputDiv = document.getElementById(\'custom-input\');\n        const calculateBtn = document.getElementById(\'calculate-btn\');\n        const numberDisplay = document.getElementById(\'number-display\');\n        const frequencyDisplay = document.getElementById(\'frequency-display\');\n        const playBtn = document.getElementById(\'play-btn\');\n        const stopBtn = document.getElementById(\'stop-btn\');\n        const harmonizeBtn = document.getElementById(\'harmonize-btn\');\n        const toneMeaning = document.getElementById(\'tone-meaning\');\n        const visualizationBars = document.querySelectorAll(\'.bar\');\n        \n        // Show/hide input fields based on calculation type\n        calculationType.addEventListener(\'change\', function() {\n            lifePathInput.style.display = \'none\';\n            nameInputDiv.style.display = \'none\';\n            customInputDiv.style.display = \'none\';\n            \n            if (this.value === \'lifePath\' || this.value === \'birthDate\') {\n                lifePathInput.style.display = \'block\';\n            } else if (this.value === \'name\') {\n                nameInputDiv.style.display = \'block\';\n            } else if (this.value === \'custom\') {\n                customInputDiv.style.display = \'block\';\n            }\n        });\n        \n        // Calculate numerology number based on input\n        calculateBtn.addEventListener(\'click\', function() {\n            let number;\n            const type = calculationType.value;\n            \n            if (type === \'lifePath\' || type === \'birthDate\') {\n                if (!birthDateInput.value) {\n                    alert(\'Please enter your birth date\');\n                    return;\n                }\n                number = calculateLifePathNumber(birthDateInput.value);\n            } else if (type === \'name\') {\n                if (!nameInput.value.trim()) {\n                    alert(\'Please enter your name\');\n                    return;\n                }\n                number = calculateNameNumber(nameInput.value);\n            } else { // custom\n                number = parseInt(customInput.value);\n            }\n            \n            // Display results\n            numberDisplay.textContent = number;\n            frequencyDisplay.textContent = frequencies[number] + \" Hz\";\n            toneMeaning.textContent = meanings[number];\n            \n            // Enable tone buttons\n            playBtn.disabled = false;\n            stopBtn.disabled = false;\n            harmonizeBtn.disabled = false;\n            \n            // Add animation to show result is updated\n            const resultDisplay = document.querySelector(\'.result-display\');\n            resultDisplay.style.animation = \'none\';\n            setTimeout(() => {\n                resultDisplay.style.animation = \'pulse 1s\';\n            }, 10);\n        });\n        \n        // Calculate Life Path Number from birth date\n        function calculateLifePathNumber(dateString) {\n            const dateParts = dateString.split(\'-\');\n            const year = dateParts[0];\n            const month = dateParts[1];\n            const day = dateParts[2];\n            \n            // Sum all digits\n            let sum = sumDigits(day) + sumDigits(month) + sumDigits(year);\n            \n            // Reduce to a single digit (1-9)\n            return reduceToSingleDigit(sum);\n        }\n        \n        // Calculate Name Number using alphabetical position\n        function calculateNameNumber(name) {\n            name = name.toLowerCase().replace(/[^a-z]/g, \'\');\n            let sum = 0;\n            \n            for (let i = 0; i < name.length; i++) {\n                // a=1, b=2, etc.\n                const value = name.charCodeAt(i) - 96;\n                sum += value;\n            }\n            \n            return reduceToSingleDigit(sum);\n        }\n        \n        // Sum all digits in a number\n        function sumDigits(num) {\n            let sum = 0;\n            num = String(num);\n            \n            for (let i = 0; i < num.length; i++) {\n                sum += parseInt(num[i]);\n            }\n            \n            return sum;\n        }\n        \n        // Reduce number to a single digit (1-9)\n        function reduceToSingleDigit(num) {\n            while (num > 9) {\n                num = sumDigits(num);\n            }\n            return num;\n        }\n        \n        // Play the tone\n        playBtn.addEventListener(\'click\', function() {\n            stopTone(); // Stop any playing tone first\n            \n            const number = parseInt(numberDisplay.textContent);\n            const frequency = frequencies[number];\n            \n            if (!frequency) return;\n            \n            // Create audio context if not already created\n            if (!audioContext) {\n                audioContext = new (window.AudioContext || window.webkitAudioContext)();\n            }\n            \n            // Create oscillator\n            oscillator = audioContext.createOscillator();\n            oscillator.type = \'sine\';\n            oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);\n            \n            // Add fade in\n            gainNode = audioContext.createGain();\n            gainNode.gain.setValueAtTime(0, audioContext.currentTime);\n            gainNode.gain.linearRampToValueAtTime(0.3, audioContext.currentTime + 0.5);\n            \n            // Connect nodes\n            oscillator.connect(gainNode);\n            gainNode.connect(audioContext.destination);\n            \n            // Start oscillator\n            oscillator.start();\n            \n            // Start visualization\n            startVisualization();\n            \n            // Update button states\n            playBtn.disabled = true;\n            stopBtn.disabled = false;\n            harmonizeBtn.disabled = false;\n        });\n        \n        // Stop the tone\n        stopBtn.addEventListener(\'click\', stopTone);\n        \n        function stopTone() {\n            if (oscillator) {\n                // Fade out\n                if (gainNode) {\n                    gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.5);\n                    setTimeout(() => {\n                        oscillator.stop();\n                        oscillator.disconnect();\n                        oscillator = null;\n                    }, 500);\n                } else {\n                    oscillator.stop();\n                    oscillator.disconnect();\n                    oscillator = null;\n                }\n            }\n            \n            // Stop harmonic oscillators with slight delays for natural feeling\n            harmonicOscillators.forEach((osc, index) => {\n                if (osc && osc.gainNode) {\n                    osc.gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.3 + (index * 0.1));\n                    setTimeout(() => {\n                        osc.stop();\n                        osc.disconnect();\n                    }, 300 + (index * 100));\n                } else if (osc) {\n                    osc.stop();\n                    osc.disconnect();\n                }\n            });\n            harmonicOscillators = [];\n            \n            // Stop visualization\n            stopVisualization();\n            \n            // Update button states\n            if (numberDisplay.textContent !== \'--\') {\n                playBtn.disabled = false;\n            }\n        }\n        \n        // Add harmonic layers\n        harmonizeBtn.addEventListener(\'click\', function() {\n            if (!audioContext || !oscillator) return;\n            \n            const number = parseInt(numberDisplay.textContent);\n            const baseFrequency = frequencies[number];\n            \n            // Clear existing harmonics first\n            harmonicOscillators.forEach(osc => {\n                if (osc) {\n                    osc.stop();\n                    osc.disconnect();\n                }\n            });\n            harmonicOscillators = [];\n            \n            // Create harmonic oscillators with golden ratio relationships\n            const harmonics = [\n                baseFrequency * 1.618, // Golden ratio\n                baseFrequency * 2,     // Octave\n                baseFrequency / 1.618, // Lower golden ratio\n                baseFrequency * 1.5,   // Perfect fifth\n            ];\n            \n            harmonics.forEach((freq, index) => {\n                const harmOsc = audioContext.createOscillator();\n                harmOsc.type = index % 2 === 0 ? \'sine\' : \'triangle\';\n                harmOsc.frequency.setValueAtTime(freq, audioContext.currentTime);\n                \n                const harmGain = audioContext.createGain();\n                harmGain.gain.setValueAtTime(0, audioContext.currentTime);\n                harmGain.gain.linearRampToValueAtTime(0.1, audioContext.currentTime + 0.5 + (index * 0.2));\n                \n                harmOsc.connect(harmGain);\n                harmGain.connect(audioContext.destination);\n                \n                harmOsc.start();\n                harmOsc.gainNode = harmGain; // Store gain node for fade out later\n                harmonicOscillators.push(harmOsc);\n            });\n            \n            // Disable harmonize button temporarily\n            harmonizeBtn.disabled = true;\n            setTimeout(() => {\n                harmonizeBtn.disabled = false;\n            }, 1000);\n        });\n        \n        // Visual animations\n        let visualizationInterval;\n        \n        function startVisualization() {\n            stopVisualization(); // Clear any existing interval\n            \n            const number = parseInt(numberDisplay.textContent);\n            const baseHeight = number * 5 + 30; // Base height varies by number (35% to 75%)\n            \n            visualizationInterval = setInterval(() => {\n                visualizationBars.forEach((bar, index) => {\n                    // Create more natural wave-like pattern\n                    const phase = Date.now() / 200 + index * 0.2;\n                    const sinValue = Math.sin(phase);\n                    const height = baseHeight + sinValue * 15; // Vary by +/- 15%\n                    bar.style.height = `\${height}%`;\n                    \n                    // Subtle color variation\n                    const hue = 25; // Orange\n                    const lightness = 50 + sinValue * 10;\n                    bar.style.background = `linear-gradient(180deg, \n                        hsl(\${hue}, 100%, \${lightness + 10}%), \n                        hsl(\${hue}, 100%, \${lightness - 10}%))`;\n                });\n            }, 50);\n        }\n        \n        function stopVisualization() {\n            if (visualizationInterval) {\n                clearInterval(visualizationInterval);\n                visualizationBars.forEach(bar => {\n                    bar.style.height = \'30%\';\n                    bar.style.background = `linear-gradient(180deg, var(--primary-light), var(--primary-dark))`;\n                });\n            }\n        }\n        \n        // Initialize date picker to today by default\n        const today = new Date().toISOString().split(\'T\')[0];\n        birthDateInput.value = today;\n    </script>\n</body>\n</html>',
            height: 823.1,
            verticalScroll: false,
            horizontalScroll: false,
            html: true,
          ),
